def get_template_image(char_name):
    key = CHAR_TO_TEMPLATE.get(char_name, "K")
    b64 = CHARACTER_TEMPLATES.get(key, CHARACTER_TEMPLATES["DEFAULT"])
    try:
        data = base64.b64decode(b64)
        img = Image.open(io.BytesIO(data)).convert('RGB')
        return img
    except:
        return None

CACHE = OrderedDict()
def get_cache(uid):
    if uid in CACHE:
        ts,d = CACHE[uid]
        if time.time()-ts<300: return d
        del CACHE[uid]
    return None
def set_cache(uid,data):
    CACHE[uid]=(time.time(),data)
    if len(CACHE)>200: CACHE.popitem(last=False)

def safe_json(url,timeout=12):
    try:
        r=requests.get(url,headers={"User-Agent":"Mozilla/5.0"},timeout=timeout)
        if not r.text or r.text.strip().startswith("<"): return None
        if len(r.text.strip())<10: return None
        return r.json()
    except: return None

def parse_player(raw):
    if not raw: return None
    data=raw
    if isinstance(raw,dict) and "data" in raw and isinstance(raw["data"],dict):
        data=raw["data"]
    def find(keys,default="?"):
        for k in keys:
            if isinstance(data,dict) and k in data:
                v=data[k]
                if isinstance(v,(str,int,float)) and str(v).strip()!="": return v
            if isinstance(data,dict):
                for dk,dv in data.items():
                    if dk.lower()==k.lower():
                        if isinstance(dv,(str,int,float)) and str(dv).strip()!="": return dv
        # deep
        def deep(o,d=0):
            if d>8: return None
            if isinstance(o,dict):
                for kk,vv in o.items():
                    if kk.lower() in [x.lower() for x in keys]:
                        if isinstance(vv,(str,int,float)) and str(vv).strip()!="":
                            return vv
                    r=deep(vv,d+1)
                    if r: return r
            elif isinstance(o,list):
                for it in o:
                    r=deep(it,d+1)
                    if r: return r
            return None
        r=deep(data)
        return r if r is not None else default
    nick=find(["nickname","accountName","playerName"],"Unknown")
    lvl=find(["level","AccountLevel"],"?" )
    likes=find(["liked","likes"],"?" )
    region=find(["region"],"IND")
    guild=find(["clanName","guildName","clan"],"No Guild")
    if not guild or str(guild).lower() in ["null","none"]: guild="No Guild"
    basic=data.get("basicInfo",{}) if isinstance(data,dict) else {}
    if isinstance(basic,dict):
        if nick=="Unknown": nick=basic.get("nickname",nick)
        if lvl=="?": lvl=basic.get("level",lvl)
        if likes=="?": likes=basic.get("liked",likes)
    clan=data.get("clanBasicInfo",{}) if isinstance(data,dict) else {}
    if isinstance(clan,dict) and guild=="No Guild":
        guild=clan.get("clanName",guild)
    return {"nickname":str(nick)[:20],"level":str(lvl),"likes":str(likes),"region":str(region),"guild":str(guild)[:20]}

def get_equip_with_ids(outfit,raw):
    items=[]
    def extract(obj):
        if isinstance(obj,dict):
            for k,v in obj.items():
                kl=k.lower()
                if kl in ["outfits","clothes","items","costumes"]:
                    if isinstance(v,list):
                        for it in v:
                            if isinstance(it,dict):
                                iid=it.get("itemId") or it.get("id") or it.get("clothesId") or it.get("item_id")
                                name=it.get("name") or it.get("itemName") or it.get("displayName") or ""
                                if iid or name:
                                    items.append({"id":str(iid) if iid else "","name":str(name)[:18]})
                            elif isinstance(it,str) and len(it)>2:
                                items.append({"id":"","name":it[:18]})
                if isinstance(v,(dict,list)):
                    extract(v)
        elif isinstance(obj,list):
            for it in obj:
                extract(it)
    if outfit: extract(outfit)
    if raw: extract(raw)
    # dedup
    seen=set()
    uniq=[]
    for it in items:
        key=(it["id"]+it["name"]).lower()
        if key not in seen and it["name"] and len(it["name"])>2:
            if it["name"].lower() not in ["ind","sg","no guild","k","alok"]:
                seen.add(key)
                uniq.append(it)
    return uniq[:8]

def detect_char(raw,outfit):
    def find_id(o):
        if isinstance(o,dict):
            for k,v in o.items():
                if k.lower() in ["characterid","equippedcharacterid"]:
                    if str(v).isdigit(): return str(v)
                if isinstance(v,(dict,list)):
                    r=find_id(v)
                    if r: return r
        elif isinstance(o,list):
            for it in o:
                r=find_id(it)
                if r: return r
        return None
    cid=None
    if raw: cid=find_id(raw)
    if not cid and outfit: cid=find_id(outfit)
    if cid and cid in FF_CHAR_MAP: return FF_CHAR_MAP[cid],cid
    # name fallback
    s=json.dumps(raw).lower() if raw else ""
    if outfit: s+=json.dumps(outfit).lower()
    for k,v in FF_CHAR_MAP.items():
        if v.lower() in s: return v,k
    return "K","8"

def get_player(uid):
    for url in [f"https://wzapi.vercel.app/get_all?uid={uid}&region=IND",f"https://wzapi.vercel.app/get?uid={uid}&region=IND",f"https://wzapi.vercel.app/get?uid={uid}&region=SG"]:
        d=safe_json(url,11)
        if d:
            ss=json.dumps(d).lower()
            if "player not found" in ss and len(ss)<800: continue
            if any(k in ss for k in ["nickname","basicinfo"]): return d
        time.sleep(0.2)
    return None

def get_outfit(uid):
    for url in [f"https://wzapi.vercel.app/outfit?uid={uid}&region=IND",f"https://wzapi.vercel.app/outfit?uid={uid}&region=SG"]:
        d=safe_json(url,9)
        if d and len(str(d))>30: return d
        time.sleep(0.15)
    return None

def get_ban(uid):
    cached=get_cache(uid)
    if cached: return cached
    for url in [f"https://wzapi.vercel.app/check_ban?uid={uid}",f"https://wzapiinfo.vercel.app/check_ban?uid={uid}"]:
        d=safe_json(url,8)
        if d:
            try:
                data=d.get("data",d) if isinstance(d,dict) else d
                if isinstance(data,dict):
                    ib=data.get("is_banned",data.get("banned"))
                    per=data.get("period",data.get("ban_period",0))
                    if ib is None and str(data.get("status","")).upper()=="OK": ib=False
                    if ib is not None:
                        banned=1 if str(ib).lower() in ["1","true","banned","yes"] else 0
                        if banned==0:
                            res=(0,per,"NOT BANNED","No Ban","-",False)
                        else:
                            try:
                                p=int(str(per)) if per else 0
                                if p==0 or p>=9999 or p>3650:
                                    res=(1,per,"PERMANENT BANNED","Permanent","Never",True)
                                else:
                                    exp=(datetime.now()+timedelta(days=p)).strftime("%d %b %Y")
                                    res=(1,per,f"TEMP BANNED - {p} DAYS",f"{p} Days",exp,True)
                            except:
                                res=(1,per,"BANNED",str(per),"Unknown",True)
                        set_cache(uid,res)
                        return res
            except: pass
        time.sleep(0.15)
    return (0,0,"NOT BANNED","No Ban","-",False)

def get_item_icon(item_id):
    if not item_id or not item_id.isdigit(): return None
    urls=[
        f"https://freefiresite.vercel.app/icon?item={item_id}",
        f"https://api.freefireinfo.site/icon?id={item_id}",
    ]
    for url in urls:
        try:
            r=requests.get(url,timeout=5,headers={"User-Agent":"Mozilla/5.0"})
            if r.status_code==200 and len(r.content)>1000 and 'image' in r.headers.get('content-type',''):
                img=Image.open(io.BytesIO(r.content)).convert('RGBA')
                return img
        except: continue
    return None

def generate_reference_image(player, equip_list, char):
    """Generate image EXACTLY like reference - character middle, 8 hexagons with icons"""
    char_name=char[0] if isinstance(char,tuple) else str(char)
    base=get_template_image(char_name)
    if not base:
        W,H=1080,1350
        base=Image.new('RGB',(W,H),(18,10,45))
    W,H=base.size
    # Resize to reference aspect - taller
    if W<1000:
        base=base.resize((1080,int(H*1080/W)),Image.Resampling.LANCZOS)
        W,H=base.size
    
    img=base.copy()
    draw=ImageDraw.Draw(img,'RGBA')
    
    # Platform already in base, but enhance
    cx,cy=W//2,H//2+60
    
    # Hexagon positions - EXACTLY like reference image
    hex_size=62
    # Left side 4, Right side 4
    left_x=cx-320
    right_x=cx+320
    positions=[
        (left_x+60, cy-180),   # top left
        (left_x-30, cy-80),    # mid top left
        (left_x-30, cy+60),    # mid bottom left
        (left_x+60, cy+170),   # bottom left
        (right_x-60, cy-180),  # top right
        (right_x+30, cy-80),   # mid top right
        (right_x+30, cy+60),   # mid bottom right
        (right_x-60, cy+170),  # bottom right
    ]
    
    def draw_hexagon(center,size,icon_img=None,has_item=True):
        x,y=center
        pts=[]
        for i in range(6):
            ang=math.radians(60*i-30)
            pts.append((x+size*math.cos(ang),y+size*math.sin(ang)))
        # Outer glow
        if has_item:
            glow=[]
            for i in range(6):
                ang=math.radians(60*i-30)
                glow.append((x+(size+8)*math.cos(ang),y+(size+8)*math.sin(ang)))
            draw.polygon(glow,fill=(160,80,255,50))
        # Hexagon bg dark
        draw.polygon(pts,fill=(25,12,55),outline=(140,70,255) if has_item else (70,35,110),width=3)
        # Inner
        inner=[]
        for i in range(6):
            ang=math.radians(60*i-30)
            inner.append((x+size*0.72*math.cos(ang),y+size*0.72*math.sin(ang)))
        draw.polygon(inner,fill=(40,18,75,200))
        # Icon
        if icon_img and has_item:
            try:
                # Resize icon to fit
                icon_size=size*0.9
                icon_img=icon_img.resize((int(icon_size),int(icon_size)),Image.Resampling.LANCZOS)
                # Paste centered
                ix=int(x-icon_size/2)
                iy=int(y-icon_size/2)
                img.paste(icon_img,(ix,iy),icon_img if icon_img.mode=='RGBA' else None)
            except:
                pass
        elif has_item:
            # Fallback - draw initial letter
            try:
                font=ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",18)
            except:
                font=ImageFont.load_default()
            draw.text((x-10,y-10),"★",fill=(200,150,255),font=font)
    
    # Draw connections first (behind hexagons)
    for idx,(hx,hy) in enumerate(positions):
        has_item=idx < len(equip_list)
        if has_item:
            # Line from hexagon to character
            draw.line([(hx,hy),(cx,cy)],fill=(120,70,200,120),width=2)
        else:
            draw.line([(hx,hy),(cx,cy)],fill=(60,30,90,60),width=1)
    
    # Draw hexagons with icons
    for idx,(hx,hy) in enumerate(positions):
        has_item=idx < len(equip_list)
        icon=None
        if has_item:
            item=equip_list[idx]
            if item.get("id"):
                icon=get_item_icon(item["id"])
        draw_hexagon((hx,hy),hex_size,icon,has_item)
    
    # No text on image - clean like reference, text will be in caption
    return img

