async def handle_uid(update,context,uids,mode="info"):
    await context.bot.send_chat_action(chat_id=update.effective_chat.id,action=ChatAction.TYPING)
    status=await update.message.reply_text(f"🔍 Checking <code>{uids[0]}</code>... ⏳",parse_mode=ParseMode.HTML)
    for uid in uids[:1]:
        raw=get_player(uid)
        if not raw:
            await status.edit_text(f"❌ UID <code>{uid}</code> Not Found",parse_mode=ParseMode.HTML)
            return
        await status.edit_text(f"✅ UID <code>{uid}</code> Found! 🎨 Creating reference image... ✨",parse_mode=ParseMode.HTML)
        outfit=get_outfit(uid)
        ban=get_ban(uid)
        cname,cid=detect_char(raw,outfit)
        parsed=parse_player(raw)
        if not parsed: parsed={"nickname":"Unknown","level":"?","likes":"?","region":"IND","guild":"No Guild"}
        equip=get_equip_with_ids(outfit,raw)
        is_banned,per,ban_status,timer,expire,banned_bool=ban
        # Generate reference style image
        player_for_img={"uid":uid}
        img=generate_reference_image(player_for_img,equip,(cname,cid))
        # Excellent caption
        if mode=="ban":
            if banned_bool:
                cap=f"<b>🔴 BAN CHECK 🔴</b>\n\n🆔 <code>{uid}</code> | 👤 {parsed['nickname']}\n⭐ Lv:{parsed['level']} | ❤️ {parsed['likes']} | 👥 {parsed['guild']}\n\n{'🚫' if banned_bool else '✅'} <b>{ban_status}</b>\n⏰ {timer}" + (f"\n📅 {expire}" if expire!="-" else "")
            else:
                cap=f"<b>🟢 BAN CHECK 🟢</b>\n\n🆔 <code>{uid}</code> | 👤 {parsed['nickname']}\n⭐ Lv:{parsed['level']} | ❤️ {parsed['likes']} | 👥 {parsed['guild']}\n\n✅ <b>{ban_status}</b>\n🎉 NOT BANNED!"
        else:
            ban_line=f"🚫 {ban_status} | ⏰ {timer}" if banned_bool else f"✅ {ban_status}"
            equip_txt=""
            if equip:
                equip_txt="\n\n🎒 <b>Equipment:</b>\n"
                for i,it in enumerate(equip[:8]):
                    equip_txt+=f"{'└' if i==len(equip[:8])-1 else '├'} {it['name']}\n"
            cap=f"<b>🟢 PLAYER INFO 🟢</b>\n\n🆔 <code>{uid}</code> | 👤 {parsed['nickname']}\n⭐ Level: {parsed['level']} | ❤️ Likes: {parsed['likes']}\n🌍 {parsed['region']} | 👥 Guild: {parsed['guild']}\n🎭 Character: {cname}\n\n{ban_line}{equip_txt}"
        try:
            if img:
                path=f"/tmp/ff_ref_{uid}.jpg"
                img.save(path,"JPEG",quality=92)
                with open(path,'rb') as f:
                    await context.bot.send_photo(chat_id=update.effective_chat.id,photo=f,caption=cap,parse_mode=ParseMode.HTML,reply_markup=get_inline())
                await status.delete()
            else:
                await status.edit_text(cap,parse_mode=ParseMode.HTML,reply_markup=get_inline())
        except Exception as e:
            await status.edit_text(f"{cap}\nErr:{str(e)[:60]}",parse_mode=ParseMode.HTML,reply_markup=get_inline())

async def check_cmd(update,context):
    uids=[p for a in context.args for p in a.replace(","," ").split() if p.isdigit() and 6<=len(p)<=15]
    if not uids:
        await update.message.reply_text("<code>12345678</code>",parse_mode=ParseMode.HTML,reply_markup=get_main_keyboard())
        return
    await handle_uid(update,context,uids,"info")

async def cb(update,context):
    q=update.callback_query
    await q.answer()
    if q.data=="again":
        await q.message.reply_text("🔄 UID bhejo: <code>12345678</code>",parse_mode=ParseMode.HTML,reply_markup=get_main_keyboard())
    elif q.data=="menu":
        await start(q,context)

async def text_handler(update,context):
    txt=update.message.text.strip()
    if "1. Ban Check" in txt:
        await update.message.reply_text("🔴 Ban Check - UID bhejo:",parse_mode=ParseMode.HTML,reply_markup=get_main_keyboard())
        return
    elif "2. Player Info" in txt:
        await update.message.reply_text("🟢 Player Info - UID bhejo:",parse_mode=ParseMode.HTML,reply_markup=get_main_keyboard())
        return
    elif "3. Owner Info" in txt:
        await owner_info(update,context)
        return
    found=re.findall(r'\d{6,15}',txt)
    valid=[u for u in found if 6<=len(u)<=15]
    if valid:
        mode="ban" if "ban" in txt.lower() else "info"
        await handle_uid(update,context,valid,mode)
    else:
        await update.message.reply_text("<code>12345678</code>",parse_mode=ParseMode.HTML,reply_markup=get_main_keyboard())

def main():
    try: asyncio.get_event_loop()
    except RuntimeError: asyncio.set_event_loop(asyncio.new_event_loop())
    threading.Thread(target=run_flask,daemon=True).start()
    app=ApplicationBuilder().token(TOKEN).build()
    app.add_handler(CommandHandler("start",start))
    app.add_handler(CommandHandler("help",start))
    app.add_handler(CommandHandler("owner",owner_info))
    app.add_handler(CommandHandler("id",check_cmd))
    app.add_handler(CommandHandler("check",check_cmd))
    app.add_handler(CommandHandler("ban",check_cmd))
    app.add_handler(CommandHandler("info",check_cmd))
    app.add_handler(CallbackQueryHandler(cb))
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND,text_handler))
    print("🔥 REFERENCE IMAGE STYLE - READY 🔥")
    app.run_polling(close_loop=False)

if __name__=="__main__": main()
